.bgfx .chy{top:0;bottom:0;left:0;width:1px;transform:translateX(var(--mx,-10px))}
.bgfx .xy{position:absolute;left:0;top:0;opacity:0;transition:opacity .2s ease;transform:translate(calc(var(--mx,-200px) + 12px),calc(var(--my,-200px) + 12px));
