// node shots.mjs <file> <outdir> : batch of screenshots in one Chrome session
import { spawn } from 'node:child_process';
import { pathToFileURL } from 'node:url';
import { writeFileSync } from 'node:fs';
const [file, out] = process.argv.slice(2);
const port = 9300 + Math.floor(Math.random() * 500);
const proc = spawn('C:/Program Files/Google/Chrome/Application/chrome.exe', ['--headless=new', `--remote-debugging-port=${port}`, '--window-size=1440,900', '--user-data-dir=' + process.env.TEMP + '/cdp/prof' + port, 'about:blank'], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let ws; for (let i = 0; i < 40; i++) { try { const l = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); const p = l.find((t) => t.type === 'page'); if (p) { ws = new WebSocket(p.webSocketDebuggerUrl); break; } } catch {} await sleep(250); }
await new Promise((r) => ws.addEventListener('open', r, { once: true }));
let id = 0; const pend = new Map();
ws.addEventListener('message', (e) => { const m = JSON.parse(e.data); if (m.id && pend.has(m.id)) { pend.get(m.id)(m); pend.delete(m.id); } });
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pend.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expression) => { const r = (await send('Runtime.evaluate', { expression, returnByValue: true })).result; return r?.exceptionDetails ? 'EXC ' + r.exceptionDetails.exception?.description?.slice(0, 160) : r?.result?.value; };
const url = pathToFileURL(file).href;
const shots = [
  ['d-hero', 1440, 900, 'dark', 0], ['l-hero', 1440, 900, 'light', 0],
  ['d-mid', 1440, 900, 'dark', 2300], ['d-end', 1440, 900, 'dark', 99999],
  ['m-hero', 390, 844, 'dark', 0], ['m-mid', 390, 844, 'light', 1500],
];
for (const [name, w, h, theme, y] of shots) {
  await send('Emulation.setDeviceMetricsOverride', { width: w, height: h, deviceScaleFactor: 1, mobile: w < 600 });
  await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-color-scheme', value: theme }] });
  await send('Page.navigate', { url }); await sleep(1300);
  await ev(`scrollTo(0, ${y})`); await sleep(450);
  const info = await ev(`JSON.stringify({sw:document.documentElement.scrollWidth, h:document.documentElement.scrollHeight})`);
  const s = await send('Page.captureScreenshot', { format: 'png' }); writeFileSync(`${out}/${name}.png`, Buffer.from(s.result.data, 'base64'));
  console.log(name, info);
}
proc.kill(); process.exit(0);
EOF
